/* @autogenerated */
package net.civeira.phylax.integrationtest.features.oauth.flow;

import java.time.Duration;
import java.time.Instant;
import java.util.Map;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.Tag;
import org.junit.jupiter.api.Test;

import com.auth0.jwt.JWT;
import com.auth0.jwt.JWTCreator.Builder;

import io.quarkus.test.junit.QuarkusTest;
import io.restassured.path.json.JsonPath;
import io.restassured.response.Response;
import net.civeira.phylax.features.oauth.tokensecurity.domain.TokenIntrospectionResult;
import net.civeira.phylax.integrationtest.features.oauth.fixtures.OidcTestFixtures;

/**
 * Integration tests for the RFC 7662 token introspection endpoint.
 *
 * Covers: - Active token → active:true with claims - Expired token → active:false - Revoked token →
 * active:false - Invalid/random token → active:false - Missing client credentials → 401
 */
@Tag("oidc-flow")
@QuarkusTest
class TokenIntrospectionTest extends OidcIntegrationTestBase {

  /**
   * An active, recently issued access token must be introspected as active with the correct claims.
   */
  @Test
  void activeToken_returnsActiveWithClaims() {
    Response tokenResp = client.passwordGrant(OidcTestFixtures.TENANT, OidcTestFixtures.CLIENT_ID,
        OidcTestFixtures.CLIENT_SECRET, OidcTestFixtures.USERNAME, OidcTestFixtures.PASSWORD,
        OidcTestFixtures.SCOPE);
    Assertions.assertEquals(200, tokenResp.statusCode());

    String accessToken = tokenResp.jsonPath().getString("access_token");
    Assertions.assertNotNull(accessToken);

    Map<String, Object> claims = decodeToken(accessToken);
    String jti = String.valueOf(claims.get("jti"));

    tokenLookupGateway.storeByJti(jti,
        TokenIntrospectionResult.builder().active(true).sub(OidcTestFixtures.USERNAME)
            .clientId(OidcTestFixtures.CLIENT_ID).scope(OidcTestFixtures.SCOPE).jti(jti).build());

    Response introspect = client.introspect(OidcTestFixtures.TENANT, accessToken,
        OidcTestFixtures.CLIENT_ID, OidcTestFixtures.CLIENT_SECRET);

    Assertions.assertEquals(200, introspect.statusCode());
    JsonPath json = introspect.jsonPath();
    Assertions.assertTrue(json.getBoolean("active"));
    Assertions.assertEquals(OidcTestFixtures.USERNAME, json.getString("sub"));
    Assertions.assertEquals(OidcTestFixtures.CLIENT_ID, json.getString("client_id"));
  }

  /**
   * An expired JWT (past its expiry date) must be introspected as inactive.
   */
  @Test
  void expiredToken_returnsInactive() {
    Builder builder = JWT.create().withSubject(OidcTestFixtures.USERNAME)
        .withClaim("jti", "expired-jti-12345").withArrayClaim("scope", new String[] {"openid"});
    String expiredToken = tokenSigner.sign(OidcTestFixtures.TENANT, builder,
        Instant.now().minus(Duration.ofHours(1)));

    Response introspect = client.introspect(OidcTestFixtures.TENANT, expiredToken,
        OidcTestFixtures.CLIENT_ID, OidcTestFixtures.CLIENT_SECRET);

    Assertions.assertEquals(200, introspect.statusCode());
    Assertions.assertFalse(introspect.jsonPath().getBoolean("active"));
  }

  /**
   * A token whose JTI has been revoked in the session store must be introspected as inactive.
   */
  @Test
  void revokedToken_returnsInactive() {
    Response tokenResp = client.passwordGrant(OidcTestFixtures.TENANT, OidcTestFixtures.CLIENT_ID,
        OidcTestFixtures.CLIENT_SECRET, OidcTestFixtures.USERNAME, OidcTestFixtures.PASSWORD,
        OidcTestFixtures.SCOPE);
    Assertions.assertEquals(200, tokenResp.statusCode());

    String accessToken = tokenResp.jsonPath().getString("access_token");
    Map<String, Object> claims = decodeToken(accessToken);
    String jti = String.valueOf(claims.get("jti"));

    // Token signature is valid but JTI is not registered (simulates revocation)
    tokenLookupGateway.revoke(jti);

    Response introspect = client.introspect(OidcTestFixtures.TENANT, accessToken,
        OidcTestFixtures.CLIENT_ID, OidcTestFixtures.CLIENT_SECRET);

    Assertions.assertEquals(200, introspect.statusCode());
    Assertions.assertFalse(introspect.jsonPath().getBoolean("active"));
  }

  /**
   * A random string that is not a valid JWT must be introspected as inactive.
   */
  @Test
  void invalidToken_returnsInactive() {
    Response introspect = client.introspect(OidcTestFixtures.TENANT, "not-a-valid-jwt-at-all",
        OidcTestFixtures.CLIENT_ID, OidcTestFixtures.CLIENT_SECRET);

    Assertions.assertEquals(200, introspect.statusCode());
    Assertions.assertFalse(introspect.jsonPath().getBoolean("active"));
  }

  /**
   * A request without client credentials must be rejected with HTTP 401.
   */
  @Test
  void noClientCredentials_returns401() {
    Response response = client.introspect(OidcTestFixtures.TENANT);

    Assertions.assertEquals(401, response.statusCode());
  }
}
